// src/pages/About.js
import React from "react";
import { Link } from "react-router-dom";

const About = () => {
  return (
    <>
      {/* Local CSS only for About page */}
      <style>{`
        .about-page-root {
          margin-top: 100px;          /* push below main navbar */
          min-height: calc(100vh - 120px);
          display: flex;
          justify-content: center;
          padding-bottom: 60px;
        }

        .about-page {
          max-width: 1100px;
          width: 100%;
          padding: 20px;
          color: #e6e6e6;
        }

        .about-header {
          text-align: center;
          margin-bottom: 40px;
        }

        .about-header h1 {
          font-size: 42px;
          margin-bottom: 15px;
          background: linear-gradient(to right, #00f2fe, #4facfe);
          -webkit-background-clip: text;
          -webkit-text-fill-color: transparent;
        }

        .about-header p {
          max-width: 700px;
          margin: 0 auto;
          font-size: 18px;
          opacity: 0.9;
        }

        .about-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
          gap: 20px;
          margin-top: 30px;
          margin-bottom: 40px;
        }

        .about-card {
          background: rgba(15, 15, 15, 0.9);
          border-radius: 16px;
          padding: 24px 20px;
          border: 1px solid rgba(255, 255, 255, 0.06);
          backdrop-filter: blur(10px);
          transition: transform 0.25s ease, box-shadow 0.25s ease;
        }

        .about-card:hover {
          transform: translateY(-6px);
          box-shadow: 0 0 18px rgba(0, 255, 160, 0.35);
        }

        .about-card h2 {
          font-size: 22px;
          margin-bottom: 10px;
          color: #33ff8c;
        }

        .about-card p {
          font-size: 15px;
          line-height: 1.6;
        }

        .about-card ul {
          list-style: disc;
          padding-left: 18px;
          margin-top: 4px;
        }

        .about-card ul li {
          margin-bottom: 6px;
          font-size: 15px;
        }

        .about-footer {
          text-align: center;
          margin-top: 10px;
        }

        .about-footer h2 {
          font-size: 26px;
          margin-bottom: 12px;
          color: #33ff8c;
        }

        .about-actions {
          display: flex;
          justify-content: center;
          gap: 12px;
          flex-wrap: wrap;
        }

        .btn {
          padding: 8px 18px;
          border-radius: 8px;
          font-size: 15px;
          cursor: pointer;
          transition: 0.2s ease;
          text-decoration: none;
          border: none;
        }

        .btn-primary {
          background: #33ff8c;
          color: #000;
        }

        .btn-primary:hover {
          background: #22cc6b;
        }

        .btn-secondary {
          background: #444;
          color: #fff;
        }

        .btn-secondary:hover {
          background: #666;
        }
      `}</style>

      <div className="about-page-root">
        <div className="about-page">
          <div className="about-header">
            <h1>About CodeGen4Future</h1>
            <p>
              CodeGen4Future is a competitive programming and collaboration
              platform built for students, developers, and teams who want to
              learn, practice, and compete in a modern, real-time environment.
            </p>
          </div>

          <div className="about-grid">
            <div className="about-card">
              <h2>Our Mission</h2>
              <p>
                To make coding practice, interview preparation, and contests
                accessible to everyone with a fast, intuitive, and feature-rich
                online playground.
              </p>
            </div>

            <div className="about-card">
              <h2>What You Can Do</h2>
              <ul>
                <li>Solve coding problems with an in-browser editor</li>
                <li>Compete in live contests and challenges</li>
                <li>Play 1 vs 1 duels with friends</li>
                <li>Participate in team battles and tournaments</li>
                <li>Track progress via ratings and leaderboards</li>
              </ul>
            </div>

            <div className="about-card">
              <h2>For Students & Placements</h2>
              <p>
                The platform is designed keeping campus placements and coding
                interviews in mind. Sharpen your DSA skills, compete with peers,
                and build confidence before facing real tests.
              </p>
            </div>

            <div className="about-card">
              <h2>For Teams & Communities</h2>
              <p>
                Host internal contests, organize friendly battles, and create a
                healthy competitive coding culture in your college or community.
              </p>
            </div>
          </div>

          <div className="about-footer">
            <h2>Ready to start?</h2>
            <div className="about-actions">
              <Link to="/problems" className="btn btn-primary">
                Explore Problems
              </Link>
              <Link to="/contests" className="btn btn-secondary">
                Join Contests
              </Link>
              <Link to="/duel" className="btn btn-primary">
                1 vs 1 Duel
              </Link>
            </div>
          </div>
        </div>
      </div>
    </>
  );
};

export default About;
